contracts/VerusNotarizer/NotarizationSer.content:
// SPDX-License-Identifier: MIT
// Bridge between ethereum and verus

pragma solidity >=0.8.9;
pragma abicoder v2;
import "../Libraries/VerusObjects.sol";

import "../Libraries/VerusObjectsCommon.sol";
import "../VerusBridge/UpgradeManager.sol";
import "../Storage/StorageMaster.sol";

contract NotarizationSerializer is VerusStorage {

    address immutable VETH;
    address immutable BRIDGE;
    address immutable VERUS;
    address immutable DAI;
    address immutable MKR;

    constructor(address vETH, address Bridge, address Verus, address Dai, address Mkr){

        VETH = vETH;
        BRIDGE = Bridge;
        VERUS = Verus;
        DAI = Dai;
        MKR = Mkr;
    }

    uint8 constant CURRENCY_LENGTH = 20;
    uint8 constant BYTES32_LENGTH = 32;
    uint8 constant TWO2BYTES32_LENGTH = 64;
    uint8 constant FLAG_FRACTIONAL = 1;
    uint8 constant FLAG_REFUNDING = 4;
    uint8 constant FLAG_LAUNCHCONFIRMED = 0x10;
    uint8 constant FLAG_LAUNCHCOMPLETEMARKER = 0x20;
    uint8 constant AUX_DEST_ETH_VEC_LENGTH = 22;
    uint8 constant AUX_DEST_VOTE_HASH = 21;
    uint8 constant VOTE_BYTE_POSITION = 22;
    uint8 constant REQUIREDAMOUNTOFVOTES = 100;
    uint8 constant WINNINGAMOUNT = 51;
    uint8 constant UINT64_BYTES_SIZE = 8;
    uint8 constant PROOF_TYPE_ETH = 2;
    uint32 constant FLAG_START_NOTARIZATION = 4;
    uint32 constant FLAG_LAUNCH_CONFIRMED = 8;
    uint32 constant FLAG_LAUNCH_COMPLETE = 0x100;
    uint32 constant FLAG_CONTRACT_UPGRADE = 0x200;
    uint32 constant REQUIRED_NOTARIZATION_FLAGS = FLAG_START_NOTARIZATION + FLAG_LAUNCH_CONFIRMED + FLAG_LAUNCH_COMPLETE;
    uint32 constant ALLOWED_OPTIONAL_NOTARIZATION_FLAGS = FLAG_CONTRACT_UPGRADE;
    uint32 constant ALLOWED_NOTARIZATION_FLAGS = REQUIRED_NOTARIZATION_FLAGS + ALLOWED_OPTIONAL_NOTARIZATION_FLAGS;
    enum Currency {VETH, DAI, VERUS, MKR}

    function initialize() external {
        rollingVoteIndex = VerusConstants.DEFAULT_INDEX_VALUE;
    }

    function readVarint(bytes memory buf, uint32 idx) public pure returns (uint32 v, uint32 retidx) {

        uint8 b; // store current byte content

        for (uint32 i=0; i<10; i++) {
            b = uint8(buf[i+idx]);
            v = (v << 7) | b & 0x7F;
            if (b & 0x80 == 0x80)
                v++;
            else
            return (v, idx + i + 1);
        }
        revert(); // i=10, invalid varint stream
    }

    function deserializeNotarization(bytes memory notarization) external returns (bytes32 proposerAndLaunched, 
                                                                                    bytes32 prevnotarizationtxid, 
                                                                                    bytes32 hashprevcrossnotarization, 
                                                                                    bytes32 stateRoot, 
                                                                                    uint32 height) {

        uint32 nextOffset;
        uint16 bridgeConverterLaunched;
        uint8 proposerType;
        uint32 notarizationFlags;
        uint176 proposerMain;

        VerusObjectsCommon.UintReader memory readerLen;

        readerLen = readVarintStruct(notarization, 0);    // get the length of the varint version
        readerLen = readVarintStruct(notarization, readerLen.offset);        // get the length of the flags

        notarizationFlags = uint32(readerLen.value);
        nextOffset = readerLen.offset;

        require(
            (notarizationFlags & REQUIRED_NOTARIZATION_FLAGS) == REQUIRED_NOTARIZATION_FLAGS &&
            (notarizationFlags & ~ALLOWED_NOTARIZATION_FLAGS) == 0,
            "invalid notarization flags"
        );

        assembly {
                    nextOffset := add(nextOffset, 1)  // move to read type
                    proposerType := mload(add(nextOffset, notarization))
                    if gt(and(proposerType, 0xff), 0) {
                        nextOffset := add(nextOffset, 21) // move to proposer, type and vector length
                        proposerMain := mload(add(nextOffset, notarization))
                        //remove type flags of proposer.
                        proposerMain := and(proposerMain, 0x0fffffffffffffffffffffffffffffffffffffffffff)
                    }
                 }

        if (proposerType & VerusConstants.FLAG_DEST_GATEWAY == VerusConstants.FLAG_DEST_GATEWAY)
        {
            nextOffset += VerusConstants.FLAG_DEST_GATEWAY_LENGTH;  // skip past gateway ID to get to auxdest vector length
        }

        if (proposerType & VerusConstants.FLAG_DEST_AUX == VerusConstants.FLAG_DEST_AUX)
        {
            nextOffset += 1;  // goto auxdest parent vec length position
            nextOffset = processAux(notarization, nextOffset);
            nextOffset -= 1;  // NOTE: Next Varint call takes array pos not array pos +1
        }
        //position 0 of the rolling vote is use to determine whether votes have started
        else if (rollingVoteIndex != VerusConstants.DEFAULT_INDEX_VALUE){
            castVote(address(0));
        }

        assembly {
                    nextOffset := add(nextOffset, CURRENCY_LENGTH) //skip currencyid
                 }

        (, nextOffset) = deserializeCoinbaseCurrencyState(notarization, nextOffset);

        assembly {
                    nextOffset := add(nextOffset, 4) // skip notarizationheight
                    nextOffset := add(nextOffset, BYTES32_LENGTH) // move to read prevnotarizationtxid
                    prevnotarizationtxid := mload(add(notarization, nextOffset))      // prevnotarizationtxid 
                    nextOffset := add(nextOffset, 4) //skip prevnotarizationout
                    nextOffset := add(nextOffset, BYTES32_LENGTH) // move to read hashprevcrossnotarization
                    hashprevcrossnotarization := mload(add(notarization, nextOffset))      // hashprevcrossnotarization 
                    nextOffset := add(nextOffset, 4) //skip prevheight
                    nextOffset := add(nextOffset, 1) //move to read length of notarizationcurrencystate
                }

        readerLen = readCompactSizeLE(notarization, nextOffset);    // get the length of the currencyState

        nextOffset = readerLen.offset - 1;   //readCompactSizeLE returns offset of next byte so move back to start of currencyState

        for (uint i = 0; i < readerLen.value; i++)
        {
            uint16 temp; // store the currency state flags
            (temp, nextOffset) = deserializeCoinbaseCurrencyState(notarization, nextOffset);
            bridgeConverterLaunched |= temp;
        }

        proposerAndLaunched = bytes32(uint256(proposerMain));

        if (!bridgeConverterActive && bridgeConverterLaunched > 0) {
                proposerAndLaunched |= bytes32(uint256(bridgeConverterLaunched) << VerusConstants.UINT176_BITS_SIZE);  // Shift 16bit value 22 bytes to pack in bytes32
        }

        nextOffset++; //move forwards to read le
        readerLen = readCompactSizeLE(notarization, nextOffset);    // get the length of proofroot array

        (stateRoot, height) = deserializeProofRoots(notarization, uint32(readerLen.value), nextOffset);
    }

    function deserializeCoinbaseCurrencyState(bytes memory notarization, uint32 nextOffset) private returns (uint16, uint32)
    {
        address currencyid;
        uint16 bridgeLaunched;
        uint16 flags;

        assembly {
            nextOffset := add(nextOffset, 2) // move to version
            nextOffset := add(nextOffset, 2) // move to flags
            flags := mload(add(notarization, nextOffset))      // flags 
            nextOffset := add(nextOffset, CURRENCY_LENGTH) //skip notarization currencystatecurrencyid
            currencyid := mload(add(notarization, nextOffset))      // currencyid 
        }
        flags = (flags >> 8) | (flags << 8);
        if ((currencyid == BRIDGE) && flags & (FLAG_FRACTIONAL + FLAG_REFUNDING + FLAG_LAUNCHCONFIRMED + FLAG_LAUNCHCOMPLETEMARKER) == 
            (FLAG_FRACTIONAL + FLAG_LAUNCHCONFIRMED + FLAG_LAUNCHCOMPLETEMARKER)) 
        {
            bridgeLaunched = 1;
        }
        assembly {                    

                    nextOffset := add(nextOffset, 1) // move to  read currency state length
        }
        VerusObjectsCommon.UintReader memory readerLen;

        readerLen = readCompactSizeLE(notarization, nextOffset);        // get the length currencies

        // reserves[2] contain the scaled reserve amounts for ETH and DAI
        uint daiEthVRSCMKRReserves;
        if (currencyid == BRIDGE && bridgeConverterActive) {
            daiEthVRSCMKRReserves = getReserves(notarization, nextOffset, uint8(readerLen.value));
            claimableFees[bytes32(uint256(uint160(VerusConstants.VDXF_ETH_DAI_VRSC_LAST_RESERVES)))] = daiEthVRSCMKRReserves; //store the fees in the notaryFeePool
        }

        nextOffset = nextOffset + (uint32(readerLen.value) * BYTES32_LENGTH) + 2;  

        readerLen = readVarintStruct(notarization, nextOffset);        // get the length of the initialsupply
        readerLen = readVarintStruct(notarization, readerLen.offset);        // get the length of the emitted
        readerLen = readVarintStruct(notarization, readerLen.offset);        // get the length of the supply
        nextOffset = readerLen.offset;
        assembly {
                    nextOffset := add(nextOffset, 33) //skip coinbasecurrencystate first 4 items fixed at 4 x 8
                }

        readerLen = readCompactSizeLE(notarization, nextOffset);    // get the length of the reservein array of uint64
        nextOffset = readerLen.offset + (uint32(readerLen.value) * 60) + 6;     //skip 60 bytes of rest of state knowing array size always same as first

        return (bridgeLaunched, nextOffset);
    }

    function getReserves (bytes memory notarization, uint32 nextOffset, uint8 currenciesLen) private view returns (uint) {


        Currency[4] memory currencyIndexes;

        for (uint8 i = 0; i < currenciesLen; i++)
        {
            address currency;
            assembly {
                    nextOffset := add(nextOffset, CURRENCY_LENGTH) // move to  read currency length
                    currency := mload(add(notarization, nextOffset)) // move to  read currencyid
                }
            if (currency == VETH)
            {
               currencyIndexes[i] = Currency.VETH;
            }
            else if (currency == DAI)
            {
               currencyIndexes[i] = Currency.DAI;
            }
            else if (currency == VERUS)
            {
               currencyIndexes[i] = Currency.VERUS;
            }
            else if (currency == MKR)
            {
               currencyIndexes[i] = Currency.MKR;
            }

        }

        //Skip the weights
        nextOffset = nextOffset + 1 + (uint32(currenciesLen) * 4) + 1; //move to read len of reserves

        //read the reserves, position [0..63] for DAI, [64..127] for ETH  [128..191] for VRSC pack into uint 64bit chunks
        uint256 ethToDaiRatios;
        for (uint8 i = 0; i < currenciesLen; i++)
        {
            uint64 reserve;
            assembly {
                    nextOffset := add(nextOffset, UINT64_BYTES_SIZE) // move to  read currency length
                    reserve := mload(add(notarization, nextOffset)) // move to  read currencyid
                }

            ethToDaiRatios |= uint256(serializeUint64(reserve)) << (uint256(currencyIndexes[i]) << 6);
        }

        assembly {                    
            nextOffset := add(nextOffset, 1) // move forward to read next varint.
        }

        return ethToDaiRatios;  
    }

    function deserializeProofRoots (bytes memory notarization, uint32 size, uint32 nextOffset) private view returns (bytes32 stateRoot, uint32 height)
    {
        for (uint i = 0; i < size; i++)
        {
            uint16 proofType;
            address systemID;
            bytes32 tempStateRoot;
            uint32 tempHeight;

            assembly {
                nextOffset := add(nextOffset, 2) // move to version
                nextOffset := add(nextOffset, 2) // move to read type
                proofType := mload(add(notarization, nextOffset))      // read proofType 
                nextOffset := add(nextOffset, CURRENCY_LENGTH) // move to read systemID
                systemID := mload(add(notarization, nextOffset))  
                nextOffset := add(nextOffset, 4) // move to height
                tempHeight := mload(add(notarization, nextOffset))  
                nextOffset := add(nextOffset, BYTES32_LENGTH) // move to read stateroot
                tempStateRoot := mload(add(notarization, nextOffset))  
                nextOffset := add(nextOffset, BYTES32_LENGTH) // move to read blockhash
                nextOffset := add(nextOffset, BYTES32_LENGTH) // move to power
            }

            if(systemID == VERUS)
            {
                stateRoot = tempStateRoot;
                height = serializeUint32(tempHeight); //swapendian
            }

            //swap 16bit endian
            if(((proofType >> 8) | (proofType << 8)) == PROOF_TYPE_ETH){
                assembly {
                    nextOffset := add(nextOffset, 8) // move to gasprice
                }
            }
        }

    }
    function readVarintStruct(bytes memory buf, uint idx) public pure returns (VerusObjectsCommon.UintReader memory) {
        uint8 b;
        uint64 v;
        uint retidx;

        assembly {  ///assemmbly  2267 GAS
            let end := add(idx, 10)
            let i := idx
            retidx := add(idx, 1)
            for {} lt(i, end) {} {
                b := mload(add(buf, retidx))
                i := add(i, 1)
                v := or(shl(7, v), and(b, 0x7f))
                if iszero(eq(and(b, 0x80), 0x80)) {
                    break
                }
                v := add(v, 1)
                retidx := add(retidx, 1)
            }
        }
        return VerusObjectsCommon.UintReader(uint32(retidx), v);
    }

    function processAux (bytes memory firstObj, uint32 nextOffset) private returns (uint32)
    {

            VerusObjectsCommon.UintReader memory readerLen;
            readerLen = readCompactSizeLE(firstObj, nextOffset);    // get the length of the auxDest
            nextOffset = readerLen.offset;
            uint arraySize = readerLen.value;
            address tempAddress;

            for (uint i = 0; i < arraySize; i++)
            {
                    readerLen = readCompactSizeLE(firstObj, nextOffset);    // get the length of the auxDest sub array
                    assembly {
                        tempAddress := mload(add(add(firstObj, nextOffset),AUX_DEST_ETH_VEC_LENGTH))
                    }

                    castVote(tempAddress);

                    nextOffset = (readerLen.offset + uint32(readerLen.value));
            }
            return nextOffset;
    }

    function castVote(address votetxid) private {

        // If the vote is address(0) and the vote has not started, or the vote hash has already been used, return
        if ((votetxid == address(0) && rollingVoteIndex == VerusConstants.DEFAULT_INDEX_VALUE)
                || successfulVoteHashes[votetxid] == VerusConstants.MAX_UINT256) {
            return;
        }

        // if the vote hash has not been used, save the vote start timestamp
        if(votetxid != address(0) && successfulVoteHashes[votetxid] == 0) {
            successfulVoteHashes[votetxid] = block.timestamp;
        } else if (votetxid != address(0) && (block.timestamp - successfulVoteHashes[votetxid]) > (VerusConstants.SECONDS_IN_DAY * 20)) {
            // if 20 days have passed since the vote started, set the vote hash as used
            successfulVoteHashes[votetxid] = VerusConstants.MAX_UINT256;

            // reset the rolling vote index to DEFAULT, if there are other hashes they will continue, otherwise voting will go idle.
            rollingVoteIndex = VerusConstants.DEFAULT_INDEX_VALUE;
            return;
        }

        if(rollingVoteIndex > (VerusConstants.VOTE_LENGTH - 1)) {
            rollingVoteIndex = 0;
        } else {
            rollingVoteIndex = rollingVoteIndex + 1;
        }

        // save an empty global write if the value to be written is the same as the current value
        if (votetxid != rollingUpgradeVotes[rollingVoteIndex]) {
            rollingUpgradeVotes[rollingVoteIndex] = votetxid;
        }

    }

    function readCompactSizeLE(bytes memory incoming, uint32 offset) public pure returns(VerusObjectsCommon.UintReader memory) {

        uint8 oneByte;
        assembly {
            oneByte := mload(add(incoming, offset))
        }
        offset++;
        if (oneByte < 253)
        {
            return VerusObjectsCommon.UintReader(offset, oneByte);
        }
        else if (oneByte == 253)
        {
            offset++;
            uint16 twoByte;
            assembly {
                twoByte := mload(add(incoming, offset))
            }

            return VerusObjectsCommon.UintReader(offset + 1, ((twoByte << 8) & 0xffff)  | twoByte >> 8);
        }
        else if (oneByte == 254)
        {
            offset += 3;
            uint32 fourByte;
            assembly {
                fourByte := mload(add(incoming, offset))
            }
            return VerusObjectsCommon.UintReader(offset + 3, serializeUint32(fourByte));
        }
        else
        {
            offset += 7;
            uint64 eightByte;
            assembly {
                eightByte := mload(add(incoming, offset))
            }
            return VerusObjectsCommon.UintReader(offset + 1, serializeUint64(eightByte));
        }
    }

    function serializeUint32(uint32 number) public pure returns(uint32){
        // swap bytes
        number = ((number & 0xFF00FF00) >> 8) | ((number & 0x00FF00FF) << 8);
        number = (number >> 16) | (number << 16);
        return number;
    }

    function serializeUint64(uint64 v) public pure returns(uint64){

        v = ((v & 0xFF00FF00FF00FF00) >> 8) |
        ((v & 0x00FF00FF00FF00FF) << 8);

        // swap 2-byte long pairs
        v = ((v & 0xFFFF0000FFFF0000) >> 16) |
            ((v & 0x0000FFFF0000FFFF) << 16);

        // swap 4-byte long pairs
        v = (v >> 32) | (v << 32);
        return v;
    }
}

contracts/VerusNotarizer/VerusNotarizer..content:
// SPDX-License-Identifier: MIT
// Bridge between ethereum and verus

pragma solidity >=0.8.9;
pragma abicoder v2;

import "../Libraries/VerusConstants.sol";
import "../Libraries/VerusObjectsNotarization.sol";
import "./NotarizationSerializer.sol";
import "../MMR/VerusBlake2b.sol";
import "../VerusBridge/CreateExports.sol";
import "../VerusBridge/UpgradeManager.sol";
import "../Storage/StorageMaster.sol";
import "../VerusBridge/SubmitImports.sol";

contract VerusNotarizer is VerusStorage {

    address immutable VETH;
    address immutable BRIDGE;
    address immutable VERUS;

    constructor(address vETH, address Bridge, address Verus){

        VETH = vETH;
        BRIDGE = Bridge;
        VERUS = Verus;
    }

    uint8 constant FORKS_DATA_OFFSET_FOR_HEIGHT = 224;

    uint32 constant FORKS_DATA_CONFIRMED_PROPOSER = 96;
    uint32 constant PROOF_HEIGHT_LOCATION = 68 - 32;  //NOTE: removed blockhash from proofroot, so this is now 68 bytes minus 32 bytes for the blockhash
    uint32 constant LENGTH_OF_FORK_DATA = 96;

    // notarization vdxf key
    bytes22 constant vdxfcodePlusVersion = bytes22(0x01367Eaadd291E1976ABc446A143f83c2D4D2C5a8401);
    event NewNotarization (bytes32);
    using VerusBlake2b for bytes;

    function currentNotariesLength() public view returns(uint8){

        return uint8(notaries.length);

    }

    function setLatestData(bytes calldata serializedNotarization, bytes32 txid, uint32 n, bytes calldata data
        ) external {

        require(!knownNotarizationTxids[txid], "known TXID");
        knownNotarizationTxids[txid] = true;

        (uint8[] memory _vs,
        bytes32[] memory _rs,
        bytes32[] memory _ss,
        uint32[] memory blockheights,
        address[] memory notaryAddresses) = abi.decode(data,(uint8[],bytes32[], bytes32[],uint32[],address[]));

        bytes32 keccakNotarizationHash;
        bytes32 txidHash;

        txidHash = keccak256(abi.encodePacked(txid, serializeUint32(n)));

        keccakNotarizationHash = keccak256(serializedNotarization);

        uint i;
        bytes memory tempBytes;

        tempBytes =  abi.encodePacked(
                    vdxfcodePlusVersion,
                    txidHash,
                    VERUS,
                    serializeUint32(blockheights[i]),
                    notaryAddresses[i], 
                    keccakNotarizationHash);

        for(; i < notaryAddresses.length; i++)
        {
            if (i < (notaryAddresses.length - 1)) {
                checkunique(notaryAddresses, i);
            }

            bytes32 hashedNotarizationByID;
            // hash the notarizations with the vdxf key, system, height & NotaryID. the address is masked in 98 bytes in .
            assembly {
                mstore(add(tempBytes, 98), or(and(mload(add(tempBytes, 98)), shl(160, 0xffffffffffffffffffffffff)), mload(add(notaryAddresses, mul(add(i,1), 32)))))
                hashedNotarizationByID := keccak256(add(tempBytes, 0x20), mload(tempBytes))
            }

           // hashedNotarizationByID = keccak256(tempBytes);

            if (ecrecover(hashedNotarizationByID, _vs[i]-4, _rs[i], _ss[i]) != notaryAddressMapping[notaryAddresses[i]].main)
            {
                revert("Invalid notary signature");  
            }
            if (notaryAddressMapping[notaryAddresses[i]].state != VerusConstants.NOTARY_VALID)
            {
                revert("Notary revoked"); 
            }
        }

        if(i < ((notaries.length >> 1) + 1 ))
        {
            revert("not enough notary signatures");
        }

        checkNotarization(serializedNotarization, txid, uint64(n));
    }

    function checkNotarization(bytes calldata serializedNotarization, bytes32 txid, uint64 voutAndHeight ) private {

        bytes32 blakeNotarizationHash;

        blakeNotarizationHash = serializedNotarization.createHash();

        address notarizationSerializerAddress = contracts[uint(VerusConstants.ContractType.NotarizationSerializer)];

        (bool success, bytes memory returnBytes) = notarizationSerializerAddress.delegatecall(abi.encodeWithSignature("deserializeNotarization(bytes)", serializedNotarization));
        require(success);

        (bytes32 launchedAndProposer, bytes32 prevnotarizationtxid, bytes32 hashprevnotarization, bytes32 stateRoot, 
                uint32 verusProofheight) = abi.decode(returnBytes, (bytes32, bytes32, bytes32, bytes32, uint32));

        voutAndHeight |= uint64(verusProofheight) << 32; // pack two 32bit numbers into one uint64
        launchedAndProposer |= bytes32(uint256(voutAndHeight) << VerusConstants.NOTARIZATION_VOUT_NUM_INDEX); // Also pack in the voutnum at the end of the uint256

        setNotarizationProofRoot(blakeNotarizationHash, hashprevnotarization, txid, prevnotarizationtxid, launchedAndProposer, stateRoot);

        // If the bridge is active and VRSC remaining has not been sent
        if (remainingLaunchFeeReserves != 0 && bridgeConverterActive) { 

            if (remainingLaunchFeeReserves > (VerusConstants.verusTransactionFee * 2)) {
                bool success2; bytes memory retData;
                (success2, retData) = contracts[uint(VerusConstants.ContractType.SubmitImports)].delegatecall(abi.encodeWithSelector(SubmitImports.sendBurnBackToVerus.selector, 0, VERUS, 0));
                require(success2);
                (VerusObjects.CReserveTransfer memory LPtransfer,) = abi.decode(retData, (VerusObjects.CReserveTransfer, bool)); 

                (success2, retData) = contracts[uint(VerusConstants.ContractType.CreateExport)].delegatecall(abi.encodeWithSelector(CreateExports.externalCreateExportCall.selector, abi.encode(LPtransfer, true)));
                require(success2);
                remainingLaunchFeeReserves = 0;
            }
        }
        emit NewNotarization(blakeNotarizationHash);
    }

    function decodeNotarization(uint index) public view returns (VerusObjectsNotarization.NotarizationForks[] memory)
        {
            uint32 nextOffset;

            bytes storage tempArray = bestForks[index];

            bytes32 hashOfNotarization;
            bytes32 txid;
            bytes32 packedPositions;
            bytes32 slotHash;
            VerusObjectsNotarization.NotarizationForks[] memory retval = new VerusObjectsNotarization.NotarizationForks[]((tempArray.length / LENGTH_OF_FORK_DATA) + 1);
            if (tempArray.length > 1)
            {
                bytes32 slot;
                assembly {
                            mstore(add(slot, 32),tempArray.slot)
                            slotHash := keccak256(add(slot, 32), 32)
                         }

                for (int i = 0; i < int(tempArray.length / LENGTH_OF_FORK_DATA); i++) 
                {
                    assembly {
                        hashOfNotarization := sload(add(slotHash,nextOffset))
                        nextOffset := add(nextOffset, 1)  
                        txid := sload(add(slotHash,nextOffset))

                        nextOffset := add(nextOffset, 1) 
                        packedPositions :=sload(add(slotHash,nextOffset))
                        nextOffset := add(nextOffset, 1)
                    }

                    retval[uint(i)] =  VerusObjectsNotarization.NotarizationForks(hashOfNotarization, txid, packedPositions);
                }
            }
            return retval;
        }

    function encodeNotarization(uint index, VerusObjectsNotarization.NotarizationForks memory notarizations)private  {

        if (bestForks.length < index + 1)
        {
            bestForks.push("");  //initialize empty bytes array
        }

        bestForks[index] = abi.encodePacked(bestForks[index], notarizations.hashOfNotarization, 
                                            notarizations.txid,
                                            notarizations.proposerPacked);
    }

    function encodeStandardNotarization(VerusObjectsNotarization.NotarizationForks memory firstNotarization, bytes memory secondNotarization)private  {

        bestForks[0] = abi.encodePacked(firstNotarization.hashOfNotarization, 
                                            firstNotarization.txid,
                                            firstNotarization.proposerPacked,
                                            secondNotarization);

    }

    function setNotarizationProofRoot(bytes32 hashedNotarization, 
            bytes32 hashprevnotarization, bytes32 txidHash, bytes32 hashprevtxid, bytes32 proposer, bytes32 stateRoot) private 
    {
        int forkIdx = -1;
        int forkPos;

        VerusObjectsNotarization.NotarizationForks[] memory notarizations;   
        for (int i = 0; i < int(bestForks.length) ; i++) 
        {
            notarizations =  decodeNotarization(uint(i));
            // Notarization length is always +1 more than the amount we have, as slot is ready to be filled.
            for (int j = int(notarizations.length) - 2; j >= 0; j--)
            {
                if (hashprevnotarization == notarizations[uint(j)].hashOfNotarization ||
                        hashprevtxid == notarizations[uint(j)].txid)
                {
                    forkIdx = i;
                    forkPos = j;
                    break;
                }
            }
            if (forkIdx > -1)
            {
                break;
            }
        }

        if (forkIdx == -1 && bestForks.length != 0)
        {
            revert("invalid notarization hash");
        }

        if (forkIdx == -1){
            forkIdx = 0;
        }

        if (forkPos != int(notarizations.length) - 2 && bestForks.length != 0)  
        {
            forkIdx = int(bestForks.length);
            encodeNotarization(uint(forkIdx), notarizations[uint(0)]);
        }

        // If the position that is matched is the second stored one, then that becomes the new confirmed.
        if(forkPos == 1)
        {
            if (bestForks.length > 1)
            {
                delete bestForks;
                bestForks.push("");
            }

            //pack vout in at the end of the proposer 22 bytes ctransferdest
            encodeStandardNotarization(notarizations[1], abi.encode(hashedNotarization, 
                txidHash, proposer));

            // The proofs are indexed by height, the height is stored in the proposers last 32 bits. Stored ine the proof is stateroot and the previous proof height.

            proofs[bytes32(uint256(uint32(uint256(proposer >> FORKS_DATA_OFFSET_FOR_HEIGHT))))] = abi.encodePacked(stateRoot, uint32(uint256(notarizations[1].proposerPacked) >> FORKS_DATA_OFFSET_FOR_HEIGHT));

            // Set bridge launched if confirmed notarization contains Bridge Launched bit packed on the end of proposer

            if (!bridgeConverterActive && ((uint256(notarizations[1].proposerPacked) >> VerusConstants.UINT176_BITS_SIZE) & 0xff) == 1) {
                    bridgeConverterActive = true;
            }
        }
        else
        {
            encodeNotarization(uint(forkIdx), VerusObjectsNotarization.NotarizationForks(hashedNotarization,
                txidHash, proposer));
            // Write proofs entry so that if this notarization later becomes confirmed via fork resolution,
            // getLastConfirmedVRSCStateRoot() can find its stateRoot. Without this, a fork resolution sets
            // bestForks[0] slot 2 to this notarization's height, but proofs[height] would be empty.
            proofs[bytes32(uint256(uint32(uint256(proposer >> FORKS_DATA_OFFSET_FOR_HEIGHT))))] = abi.encodePacked(stateRoot, uint32(uint256(notarizations[uint(forkPos)].proposerPacked) >> FORKS_DATA_OFFSET_FOR_HEIGHT));
        }
    }

    function checkunique(address[] memory ids, uint i) private pure
    {
        for (uint j = i + 1; j < ids.length; j++)
        {
            if (ids[i] == ids[j])
                revert("duplicate signatures found");
        }
    }

    function getProofCosts(uint256 proofOption) external pure returns (uint256) {
        uint256[3] memory feePrices = [uint256(0.01 ether),uint256(0.005 ether),uint256(0.0025 ether)];
        return feePrices[proofOption];
    }

    //users can pass in 0,1,2 to get the latest confirmed / priorconfirmed  / second prior confirmed statroot and blockhash.
    //otherwise if they enter a height the proof is free.
    // returned value is uint32 height bytes32 blockhash and bytes32 stateroot serialized together. 
    function getProof(uint256 proofHeightOptions) public payable returns (bytes memory) {

        uint256 feePrice;
        uint256 feeShare;
        uint256 remainder;

        // Price for proofs being returned.
        uint256[3] memory feePrices = [uint256(0.01 ether),uint256(0.005 ether),uint256(0.0025 ether)];

        uint256 proposerAndHeight;
        bytes memory tempBytes = bestForks[0];

        assembly {
            proposerAndHeight := mload(add(tempBytes, FORKS_DATA_CONFIRMED_PROPOSER))
        } 

        if (proofHeightOptions < 3) {
            feePrice = feePrices[proofHeightOptions];
            feeShare = (msg.value / VerusConstants.SATS_TO_WEI_STD) / 2;
            remainder = (msg.value / VerusConstants.SATS_TO_WEI_STD) % 2;

            require(msg.value == feePrice, "Not enough fee");

            // Proposer and notaries get share of fees
            // any remainder from divide by 2 or equal share to the notaries gets added to proposers share.
            claimableFees[VerusConstants.VDXF_SYSTEM_NOTARIZATION_NOTARYFEEPOOL] += feeShare;
            setClaimedFees(bytes32(uint256(uint176(proposerAndHeight))), (feeShare + remainder));
        }

        if (proofHeightOptions == 0) {
            // if the most recent confirmed is requested just get the height from the bestforks
            return abi.encodePacked(uint32(proposerAndHeight >> FORKS_DATA_OFFSET_FOR_HEIGHT), proofs[(bytes32(proposerAndHeight >> FORKS_DATA_OFFSET_FOR_HEIGHT))]);

        } else if(proofHeightOptions == 1 || proofHeightOptions == 2) {

            // if the prior confirmed or second prior confirmed notarization is required extract the height from the newest confirmed.

            tempBytes = proofs[(bytes32(proposerAndHeight >> FORKS_DATA_OFFSET_FOR_HEIGHT))];
            uint32 previousConfirmedHeight;

            assembly {
                previousConfirmedHeight := mload(add(tempBytes, PROOF_HEIGHT_LOCATION))
            } 

            if(proofHeightOptions == 1) {
                return abi.encodePacked(uint32(previousConfirmedHeight), proofs[bytes32(uint256(previousConfirmedHeight))]);
            }

            tempBytes = proofs[bytes32(uint256(previousConfirmedHeight))];

            uint32 secondPreviousConfirmedHeight;
            assembly {
                secondPreviousConfirmedHeight := mload(add(tempBytes, PROOF_HEIGHT_LOCATION))
            } 

            return abi.encodePacked(uint32(secondPreviousConfirmedHeight), proofs[bytes32(uint256(secondPreviousConfirmedHeight))]);

        } else {

           return abi.encodePacked(uint32(proofHeightOptions), proofs[bytes32(proofHeightOptions)]);
        }
    }

    function setClaimedFees(bytes32 _address, uint256 fees) private
    {
        claimableFees[_address] += fees;
    }

    function serializeUint32(uint32 number) public pure returns(uint32){
        // swap bytes
        number = ((number & 0xFF00FF00) >> 8) | ((number & 0x00FF00FF) << 8);
        number = (number >> 16) | (number << 16);
        return number;
    }


}

