contracts/VerusBridge/CreateExports.sol.content:
// SPDX-License-Identifier: MIT
// Bridge between ethereum and verus

pragma solidity >=0.8.9;
pragma abicoder v2;

import "../Libraries/VerusObjects.sol";
import "../Libraries/VerusConstants.sol";
import "./Token.sol";
import "./VerusCrossChainExport.sol";
import "./CreateExports.sol";
import "../Storage/StorageMaster.sol";
import "./ExportManager.sol";
import '@openzeppelin/contracts/token/ERC1155/IERC1155.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import "./SubmitImports.sol";

contract CreateExports is VerusStorage {

    address immutable VETH;
    address immutable BRIDGE;
    address immutable VERUS;
    address immutable DAI;
    address immutable DAIERC20ADDRESS;
    enum Currency {VETH, DAI, VERUS, MKR}
    using SafeERC20 for Token;

    constructor(address vETH, address Bridge, address Verus, address Dai, address daiERC20Address){

        VETH = vETH;
        BRIDGE = Bridge;
        VERUS = Verus;
        DAI = Dai;
        DAIERC20ADDRESS = daiERC20Address;
    }

    function initialize() external {
       // NOTE: the following code was deployed and is running. Be sure to include an initialization function in the constructor for any future changes to the contract that would require initialization logic, as the constructor will not be run on an upgrade.
       // Correct the DAI holdings to account for any DAI already in DSR at deployment time.
       // verusToERC20mapping[DAI].tokenIndex = (claimableFees[VerusConstants.VDXF_SYSTEM_DAI_HOLDINGS] / VerusConstants.SATS_TO_WEI_STD) - verusToERC20mapping[DAI].tokenIndex;
    }    

    // ******* 2026-01-05 NOTE *******
    // contract now launched so fees must always be paid by user. (contract size reduction)
    // function subtractPoolSize(uint64 _amount) private returns (bool) {

    //     if((_amount + VerusConstants.MIN_VRSC_FEE) > remainingLaunchFeeReserves) return false;
    //     remainingLaunchFeeReserves -= _amount;
    //     return true;
    // }
    // *******************************

    function sendTransfer(bytes calldata datain) payable external {

        VerusObjects.CReserveTransfer memory transfer = abi.decode(datain, (VerusObjects.CReserveTransfer));        
        sendTransferMain(transfer);
    }

    function sendTransferDirect(bytes calldata datain) payable external {

        address serializerAddress = contracts[uint(VerusConstants.ContractType.VerusSerializer)];

        (bool success, bytes memory returnData) = serializerAddress.call(abi.encodeWithSignature("deserializeTransfer(bytes)",datain));

        require(success, "deserializetransfer failed");  

        VerusObjects.CReserveTransfer memory transfer = abi.decode(returnData, (VerusObjects.CReserveTransfer));
        sendTransferMain(transfer);
    }

    function sendTransferMain(VerusObjects.CReserveTransfer memory transfer) private {

        uint256 fees;
        VerusObjects.mappedToken memory iaddressMapping;
        uint32 ethNftFlag;
        address verusExportManagerAddress = contracts[uint(VerusConstants.ContractType.ExportManager)];

        (bool success, bytes memory returnData) = verusExportManagerAddress.delegatecall(abi.encodeWithSelector(ExportManager.checkExport.selector, transfer));
        require(success, "checkExport call failed");

        fees = abi.decode(returnData, (uint256)); 

        require(fees != 0, "CheckExport Failed Checks"); 

        // ******* 2026-01-05 NOTE *******
        // bridgeConverterActive == true, so fees must always be paid by user.
        // if(!bridgeConverterActive) {
        //     require (subtractPoolSize(uint64(transfer.fees)));
        // }
        // *******************************

        if (transfer.currencyvalue.currency != VETH) {
            iaddressMapping = verusToERC20mapping[transfer.currencyvalue.currency];
            ethNftFlag = iaddressMapping.flags & (VerusConstants.MAPPING_ERC721_NFT_DEFINITION | VerusConstants.MAPPING_ERC1155_NFT_DEFINITION | VerusConstants.MAPPING_ERC1155_ERC_DEFINITION);
        }

        uint balance;

        if (ethNftFlag & (VerusConstants.MAPPING_ERC1155_NFT_DEFINITION | VerusConstants.MAPPING_ERC1155_ERC_DEFINITION) != 0) {
            IERC1155 nft = IERC1155(iaddressMapping.erc20ContractAddress);

            // TokenIndex is used for the amount of tokens held by the bridge (for erc1155's and ERC721's)
            if (ethNftFlag == VerusConstants.MAPPING_ERC1155_ERC_DEFINITION) {
                require((transfer.currencyvalue.amount + iaddressMapping.tokenIndex) < VerusConstants.MAX_VERUS_TRANSFER);
            } else {
                require(iaddressMapping.tokenIndex == 0);
            }

            verusToERC20mapping[transfer.currencyvalue.currency].tokenIndex += transfer.currencyvalue.amount;

            require (nft.isApprovedForAll(msg.sender, address(this)), "NFT not approved");
            balance = nft.balanceOf(address(this), iaddressMapping.tokenID);
            nft.safeTransferFrom(msg.sender, address(this), iaddressMapping.tokenID, transfer.currencyvalue.amount, ""); 
            require(nft.balanceOf(address(this), iaddressMapping.tokenID) == balance + transfer.currencyvalue.amount);

        } else if (ethNftFlag == VerusConstants.MAPPING_ERC721_NFT_DEFINITION) {

            VerusNft nft = VerusNft(iaddressMapping.erc20ContractAddress);
            require (nft.getApproved(iaddressMapping.tokenID) == address(this), "NFT not approved");

            require(iaddressMapping.tokenIndex == 0);
            balance = nft.balanceOf(address(this));
            nft.safeTransferFrom(msg.sender, address(this), iaddressMapping.tokenID, "");
            require(nft.balanceOf(address(this)) == balance + 1);

            if (iaddressMapping.erc20ContractAddress == verusToERC20mapping[tokenList[VerusConstants.NFT_POSITION]].erc20ContractAddress) {
                nft.burn(iaddressMapping.tokenID);
            } else {
                //Only non-verus ERC721 NFTs need their accounting to be checked as they could be non standard.
                verusToERC20mapping[transfer.currencyvalue.currency].tokenIndex += transfer.currencyvalue.amount;
            }
        } else if (transfer.currencyvalue.currency != VETH) {

            Token token = Token(iaddressMapping.erc20ContractAddress); 
            //Check user has allowed the verusBridgeStorage contract to spend on their behalf
            uint256 allowedTokens = token.allowance(msg.sender, address(this));
            uint256 tokenAmount = convertFromVerusNumber(transfer.currencyvalue.amount, token.decimals()); //convert to wei from verus satoshis
            require( allowedTokens >= tokenAmount);

            if (iaddressMapping.flags & VerusConstants.MAPPING_ETHEREUM_OWNED == VerusConstants.MAPPING_ETHEREUM_OWNED) {
                // tokenIndex is used for the amount of tokens held by the bridge  ERC20's

                require((transfer.currencyvalue.amount + iaddressMapping.tokenIndex) < VerusConstants.MAX_VERUS_TRANSFER);
                    verusToERC20mapping[transfer.currencyvalue.currency].tokenIndex += transfer.currencyvalue.amount;

            }

            exportERC20Tokens(tokenAmount, token, iaddressMapping.flags & VerusConstants.MAPPING_VERUS_OWNED == VerusConstants.MAPPING_VERUS_OWNED);
        } 

        _createExports(transfer, false);
    }

    function exportERC20Tokens(uint256 _tokenAmount, Token token, bool burn) public {

        uint256 balance;
        balance = token.balanceOf(address(this));
        token.safeTransferFrom(msg.sender, address(this), _tokenAmount);
        require(token.balanceOf(address(this)) == balance + _tokenAmount, "ERC20 transfer failed");

        // If the token is DAI, run join to have the DAI transferred to the DSR contract.
        if (address(token) == DAIERC20ADDRESS) {
            address crossChainExportAddress = contracts[uint(VerusConstants.ContractType.VerusCrossChainExport)];
            (bool success,) = crossChainExportAddress.delegatecall(abi.encodeWithSelector(VerusCrossChainExport.join.selector, _tokenAmount));
            require(success);
        }

        if (burn) 
        {
            token.burn(_tokenAmount);
        }
    }

    function externalCreateExportCallPayable(bytes memory data) external payable {

        (VerusObjects.CReserveTransfer memory reserveTransfer, bool forceNewCCE) = abi.decode(data, (VerusObjects.CReserveTransfer, bool));
        _createExports(reserveTransfer, forceNewCCE);
    }

    function externalCreateExportCall(bytes memory data) external {

        (VerusObjects.CReserveTransfer memory reserveTransfer, bool forceNewCCE) = abi.decode(data, (VerusObjects.CReserveTransfer, bool));
        _createExports(reserveTransfer, forceNewCCE);
    }

    function _createExports(VerusObjects.CReserveTransfer memory reserveTransfer, bool forceNewCCE) private {

        // If transactions over 50 and inbetween notarization boundaries, increment CCE start and endheight
        // If notarization has happened increment CCE to next boundary when the tx comes in
        // If changing from pool closed to pool open create a boundary (As all sends will then go through the bridge)
        uint64 blockNumber = uint64(block.number);
        uint64 blockDelta = blockNumber - cceLastStartHeight;
        uint64 lastTransfersLength = uint64(_readyExports[cceLastStartHeight].transfers.length);
        bytes32 prevHash = _readyExports[cceLastStartHeight].exportHash;
        // if there are no transfers then there is no need to make a new CCE as this is the first one, and the endheight can become the block number if it is less than the current block no.
        // if the last notary received height is less than the endheight then keep building up the CCE (as long as 10 ETH blocks havent passed, and a new CCE isnt being forced and there is less than 50)

        if ((cceLastEndHeight == 0 || blockDelta < 10) && !forceNewCCE  && lastTransfersLength < 50) {

            // set the end height of the CCE to the current block.number only if the current block we are on is greater than its value
            if (cceLastEndHeight < blockNumber) {
                cceLastEndHeight = blockNumber;
            }
        // if a new CCE is triggered for any reason, its startblock is always the previous endblock +1, 
        // its start height may of spilled in to virtual future block numbers so if the current cce start height is less than the block we are on we can update the end 
        // height to a new greater value.  Otherwise if the startheight is still in the future then the endheight is also in the future at the same block.
        } else {
            cceLastStartHeight = cceLastEndHeight + 1;

            if (cceLastStartHeight < blockNumber) {
                cceLastEndHeight = blockNumber;
            } else {
                cceLastEndHeight = cceLastStartHeight;
            }
        }

        if (exportHeights[cceLastEndHeight] != cceLastStartHeight) {
            exportHeights[cceLastEndHeight] = cceLastStartHeight;
        }

        setReadyExportTransfers(cceLastStartHeight, cceLastEndHeight, reserveTransfer, 50);
        VerusObjects.CReserveTransferSet memory pendingTransfers = _readyExports[cceLastStartHeight];
        address crossChainExportAddress = contracts[uint(VerusConstants.ContractType.VerusCrossChainExport)];

        (bool success, bytes memory returnData) = crossChainExportAddress.call(abi.encodeWithSignature("generateCCE(bytes)", abi.encode(pendingTransfers.transfers, bridgeConverterActive, cceLastStartHeight, cceLastEndHeight, contracts[uint(VerusConstants.ContractType.VerusSerializer)])));
        require(success, "generateCCEfailed");

        bytes memory serializedCCE = abi.decode(returnData, (bytes)); 

        if(pendingTransfers.transfers.length > 1)
        {
            prevHash = pendingTransfers.prevExportHash;
        }
        setReadyExportTxid(keccak256(abi.encodePacked(serializedCCE, prevHash)), prevHash, cceLastStartHeight);

    }

    function setReadyExportTxid(bytes32 txidhash, bytes32 prevTxidHash, uint _block) private {

        _readyExports[_block].exportHash = txidhash;

        if (_readyExports[_block].transfers.length == 1)
        {
            _readyExports[_block].prevExportHash = prevTxidHash;

        }
    }

    function setReadyExportTransfers(uint64 _startHeight, uint64 _endHeight, VerusObjects.CReserveTransfer memory reserveTransfer, uint blockTxLimit) private {

        _readyExports[_startHeight].endHeight = _endHeight;
        _readyExports[_startHeight].transfers.push(reserveTransfer);
        require(_readyExports[_startHeight].transfers.length <= blockTxLimit);
    }

    function burnFees(bytes calldata) external {

        require(bridgeConverterActive, "Bridge Converter not active");

        uint256 interestAccrued;
        uint64 truncatedInterest;
        bool success;
        bytes memory retData;

        // NOTE: Accrued interest is truncated from 18 decimals to 8, to be compatible with verus SATS.
        address crossChainExportAddress = contracts[uint(VerusConstants.ContractType.VerusCrossChainExport)];
        (success, retData) = crossChainExportAddress.delegatecall(abi.encodeWithSelector(VerusCrossChainExport.daiBalance.selector));
        require(success);

        mapping (bytes32 => uint256) storage daiTotals = claimableFees;

        interestAccrued = abi.decode(retData, (uint256)) - daiTotals[VerusConstants.VDXF_SYSTEM_DAI_HOLDINGS];

        uint256 bridgeReserveValues = daiTotals[bytes32(uint256(uint160(VerusConstants.VDXF_ETH_DAI_VRSC_LAST_RESERVES)))];

        // Multiply the cost of the Transaction to send DAI to Verus in vETH (8 decimals) by the amount of reservers in DAI.
        uint daiCalculation = (tx.gasprice * VerusConstants.DAI_BURNBACK_TRANSACTION_GAS_AMOUNT)/ VerusConstants.SATS_TO_WEI_STD * (uint64(bridgeReserveValues >> (uint(Currency.DAI) << 6)));

        // Divide the previous value by the amount of reserves in vETH (8 decimals) to get the price of the ETH transaction in DAI.
        uint64 DAIReimburseAmount = uint64(daiCalculation / uint64(bridgeReserveValues >> (uint(Currency.VETH) << 6)));

        require (DAIReimburseAmount < VerusConstants.DAI_BURNBACK_MAX_FEE_THRESHOLD &&
                    daiTotals[VerusConstants.VDXFID_DAI_BURNBACK_TIME_THRESHOLD] + VerusConstants.SECONDS_IN_DAY < block.timestamp, "Fee too high or not enough time passed");

        daiTotals[VerusConstants.VDXFID_DAI_BURNBACK_TIME_THRESHOLD] = block.timestamp;

        //truncate DAI to 8 DECIMALS of precision from 18
        truncatedInterest = uint64(interestAccrued / VerusConstants.SATS_TO_WEI_STD);

        // Recalculate the interest accrued by subtracting the amount of DAI to be reimbursed.
        interestAccrued = (truncatedInterest * VerusConstants.SATS_TO_WEI_STD) - DAIReimburseAmount;

        // The interest accrued must be a significant amount to be worth sending back to Verus.
        require (interestAccrued > VerusConstants.DAI_BURNBACK_THRESHOLD);
        // Increase the supply of DAI by the amount of interest accrued - minus the payback fee.
        daiTotals[VerusConstants.VDXF_SYSTEM_DAI_HOLDINGS] += interestAccrued;

        uint64 fees; 

        (success, retData) = contracts[uint(VerusConstants.ContractType.SubmitImports)]
                                .delegatecall(abi.encodeWithSelector(SubmitImports.getImportFeeForReserveTransfer.selector, DAI));
        require(success);

        fees = abi.decode(retData, (uint64));
        require (truncatedInterest > fees, "Not enough DAI to pay fees");

        (success, retData) = contracts[uint(VerusConstants.ContractType.SubmitImports)]
                                .delegatecall(abi.encodeWithSelector(SubmitImports.sendBurnBackToVerus.selector, truncatedInterest, DAI, fees));
        require(success);
        // When the bridge launches to make sure a fresh block with no pending vrsc transfers is used as not to mix destination currencies.
        (VerusObjects.CReserveTransfer memory LPtransfer,) = abi.decode(retData, (VerusObjects.CReserveTransfer, bool)); 

        _createExports(LPtransfer, false);

        //transfer DAI to the msg.senders address.
        (success,) = crossChainExportAddress.delegatecall(
                                                        abi.encodeWithSelector(
                                                            VerusCrossChainExport.exit.selector, 
                                                            msg.sender, 
                                                            DAIReimburseAmount * VerusConstants.SATS_TO_WEI_STD));
        require(success);

        // Add the amount sent to Verus to the DAI holdings.
        verusToERC20mapping[DAI].tokenIndex += truncatedInterest;

    }

    function convertFromVerusNumber(uint256 a,uint8 decimals) public pure returns (uint256) {
        uint8 power = 10; //default value for 18
        uint256 c = a;

        if(decimals > 8 ) {
            power = decimals - 8;// number of decimals in verus
            c = a * (10 ** power);
        }else if(decimals < 8){
            power = 8 - decimals;// number of decimals in verus
            c = a / (10 ** power);
        }

        return c;
    }
}

contracts/VerusBridge/ExportManager.sol.content:
// SPDX-License-Identifier: MIT
// Bridge between ethereum and verus
pragma solidity >=0.8.9;
pragma abicoder v2;

import "../Libraries/VerusObjects.sol";
import "../Libraries/VerusObjectsCommon.sol";
import "../Libraries/VerusConstants.sol";
import "../Storage/StorageMaster.sol";

contract ExportManager is VerusStorage  {

    address immutable VETH;
    address immutable BRIDGE;
    address immutable VERUS;
    bool runonce;

    constructor(address vETH, address Bridge, address Verus){

        VETH = vETH;
        BRIDGE = Bridge;
        VERUS = Verus;
    }

    uint8 constant UINT160_SIZE = 20; 
    uint8 constant FEE_OFFSET = 20 + 20 + 20 + 8; // 3 x 20bytes address + 64bit uint // 3 x 20bytes address + 64bit uint
    // Aux dest can only be one vector, of one vector which is a CTransferDestiantion of an R address.
    uint8 constant AUX_DEST_LENGTH = 24;

    function ERC20Registered(address _iaddress) private view returns (bool) {

        return verusToERC20mapping[_iaddress].flags > 0;

    }

    function checkExport(VerusObjects.CReserveTransfer memory transfer) external payable returns (uint256 fees){

        uint256 requiredFees = VerusConstants.transactionFee;  //0.003 eth in WEI (To vrsc) NOTE: convert to VRSC from ETH.
        int64 bounceBackFee;
        int64 transferFee;
        bytes memory serializedDest;
        address gatewayID;
        address gatewayCode;
        address destAddressID;

        require (checkTransferFlags(transfer), "Flag Check failed"); 

        serializedDest = transfer.destination.destinationaddress;  
        assembly 
        {
            destAddressID := mload(add(serializedDest, UINT160_SIZE))
        }

        if (verusToERC20mapping[transfer.currencyvalue.currency].flags & (VerusConstants.MAPPING_ERC721_NFT_DEFINITION 
            | VerusConstants.MAPPING_ERC1155_NFT_DEFINITION | VerusConstants.MAPPING_ERC1155_ERC_DEFINITION) != 0) 
        {
            require (transfer.flags == VerusConstants.VALID, "Invalid flags for NFT transfer");
            require (transfer.currencyvalue.amount == 1 
                     || verusToERC20mapping[transfer.currencyvalue.currency].flags & VerusConstants.MAPPING_ERC1155_ERC_DEFINITION 
                     == VerusConstants.MAPPING_ERC1155_ERC_DEFINITION, "Currency value must be 1 Satoshi");
            require (serializedDest.length == VerusConstants.UINT160_SIZE, "destination address not 20 bytes");
        }

        // Check destination address is not zero
        require (destAddressID != address(0), "Destination Address null");
        require (transfer.currencyvalue.currency != transfer.secondreserveid, "Cannot convert like for like");

        if (!bridgeConverterActive) {

            require (transfer.feecurrencyid == VERUS, "feecurrencyid != vrsc");

            if (transfer.destination.destinationtype == (VerusConstants.DEST_ETH + VerusConstants.FLAG_DEST_GATEWAY + VerusConstants.FLAG_DEST_AUX) ||
                transfer.flags != VerusConstants.VALID)
                return 0;

            require (transfer.destination.destinationaddress.length == VerusConstants.UINT160_SIZE, "destination address not 20 bytes");

        } else {

            transferFee = int64(transfer.fees);

            require(transfer.feecurrencyid == VETH, "Fee Currency not vETH"); //TODO:Accept more fee currencies

            if (transfer.destination.destinationtype == (VerusConstants.FLAG_DEST_GATEWAY + VerusConstants.DEST_ETH + VerusConstants.FLAG_DEST_AUX)) {

                // destinationaddress is concatenated with the gateway back address (bridge.veth) + (gatewayCode) + 0.003 ETH in fees uint64LE
                // destinationaddress is also concatenated with aux dest 
                assembly 
                {
                    gatewayID := mload(add(serializedDest, 40)) // second 20bytes in bytes array
                    gatewayCode := mload(add(serializedDest, 60)) // third 20bytes in bytes array
                    bounceBackFee := mload(add(serializedDest, FEE_OFFSET))
                }

                require (transfer.destination.destinationaddress.length == (FEE_OFFSET + AUX_DEST_LENGTH), "destination address not 68 + 24 bytes");    
                uint32 auxDestPrefix;
                address auxDestAddress;

                assembly 
                {
                    auxDestPrefix := mload(add(add(serializedDest, FEE_OFFSET), 4)) // 4bytes AUX_DEST_PREFIX_CONSTANT
                    auxDestAddress := mload(add(add(serializedDest, FEE_OFFSET), 24)) // destaddress
                }

                require (auxDestPrefix == VerusConstants.AUX_DEST_PREFIX, "auxDestPrefix Incorrect");
                require (auxDestAddress != address(0), "auxDestAddress must not be empty");
                require (gatewayID == VETH, "GatewayID not VETH");
                require (gatewayCode == address(0), "GatewayCODE must be empty");

                bounceBackFee = reverse(uint64(bounceBackFee));
                //TODO: Change bounce back fee to be the calculated fee.
                require (bounceBackFee >= int64(VerusConstants.verusvETHReturnFee), "Return fee not >= 0.01ETH");

                transferFee += bounceBackFee;
                requiredFees += convertFromVerusNumber(uint64(bounceBackFee),18);  //bounceback fees required as well as send fees

            } else if (!(transfer.destination.destinationtype == VerusConstants.DEST_PKH || transfer.destination.destinationtype == VerusConstants.DEST_ID)) {

                return 0;  

            } 

        }

        // Check fees are included in the ETH value if sending ETH, or are equal to the fee value for tokens.
        uint amount;
        amount = transfer.currencyvalue.amount;

        if (bridgeConverterActive)
        { 
            if (convertFromVerusNumber(uint64(transferFee), 18) < requiredFees)
            {
                revert ("ETH Fees to Low");
            }            
            else if (transfer.currencyvalue.currency == VETH && 
                msg.value < convertFromVerusNumber(uint256(amount + uint64(transferFee)), 18))
            {
                revert ("ETH sent < (amount + fees)");
            } 
            else if (transfer.currencyvalue.currency != VETH &&
                    msg.value < convertFromVerusNumber(uint64(transferFee), 18))
            {
                revert ("ETH fee sent < fees for token");
            } 

            return uint64(transferFee);
        }
        else 
        {
            if (transfer.fees != VerusConstants.verusTransactionFee)
            {
                revert ("Invalid VRSC fee");
            }
            else if (transfer.currencyvalue.currency == VETH &&
                     (convertFromVerusNumber(amount, 18) + requiredFees) != msg.value)
            {
                revert ("ETH Fee to low");
            }
            else if(transfer.currencyvalue.currency != VETH && requiredFees != msg.value)
            {
                revert ("ETH Fee to low (token)");
            }
            claimableFees[VerusConstants.VDXF_SYSTEM_NOTARIZATION_NOTARYFEEPOOL]  += VerusConstants.verusvETHTransactionFee;
        } 
        return requiredFees;
    }

    function checkTransferFlags(VerusObjects.CReserveTransfer memory transfer) public view returns(bool) {

        require(transfer.destsystemid == address(0), "currencycheckfailed");

        if (transfer.version != VerusConstants.CURRENT_VERSION || 
            (transfer.flags & (VerusConstants.INVALID_FLAGS | VerusConstants.VALID) ) != VerusConstants.VALID)
        {
            revert ("Invalid Flag used");
        }

        VerusObjects.mappedToken memory sendingCurrency = verusToERC20mapping[transfer.currencyvalue.currency];
        VerusObjects.mappedToken memory destinationCurrency = verusToERC20mapping[transfer.destcurrencyid];

        if (!(transfer.destination.destinationtype == (VerusConstants.DEST_ETH + VerusConstants.FLAG_DEST_GATEWAY + VerusConstants.FLAG_DEST_AUX) || 
                transfer.destination.destinationtype == VerusConstants.DEST_ID ||
                transfer.destination.destinationtype == VerusConstants.DEST_PKH) ||
                sendingCurrency.flags == 0)
        {
            revert ("Invalid desttype");
        }

        if (transfer.flags == VerusConstants.VALID && transfer.secondreserveid == address(0))
        {
            require ((transfer.destcurrencyid == (bridgeConverterActive ? BRIDGE : VERUS) && 
                     (transfer.destination.destinationtype == VerusConstants.DEST_ID ||
                      transfer.destination.destinationtype == VerusConstants.DEST_PKH)),  
                        "Invalid desttype");
        }
        else if (transfer.flags == (VerusConstants.VALID + VerusConstants.CONVERT + VerusConstants.RESERVE_TO_RESERVE))
        {
            require(sendingCurrency.flags & VerusConstants.MAPPING_PARTOF_BRIDGEVETH == VerusConstants.MAPPING_PARTOF_BRIDGEVETH &&
                    destinationCurrency.flags & VerusConstants.MAPPING_ISBRIDGE_CURRENCY == VerusConstants.MAPPING_ISBRIDGE_CURRENCY &&
                    verusToERC20mapping[transfer.secondreserveid].flags & VerusConstants.MAPPING_PARTOF_BRIDGEVETH == VerusConstants.MAPPING_PARTOF_BRIDGEVETH,
                        "Cannot convert non bridge reserves");
        }
        else if (transfer.flags == (VerusConstants.VALID + VerusConstants.CONVERT + VerusConstants.IMPORT_TO_SOURCE))
        {
            require(sendingCurrency.flags & VerusConstants.MAPPING_ISBRIDGE_CURRENCY == VerusConstants.MAPPING_ISBRIDGE_CURRENCY  &&
                    destinationCurrency.flags & VerusConstants.MAPPING_PARTOF_BRIDGEVETH == VerusConstants.MAPPING_PARTOF_BRIDGEVETH &&
                    transfer.secondreserveid == address(0),
                        "Cannot import non reserve to source");
        }
        else if (transfer.flags == (VerusConstants.VALID + VerusConstants.CONVERT))
        {
            require(sendingCurrency.flags & VerusConstants.MAPPING_PARTOF_BRIDGEVETH == VerusConstants.MAPPING_PARTOF_BRIDGEVETH  &&
                    destinationCurrency.flags & VerusConstants.MAPPING_ISBRIDGE_CURRENCY == VerusConstants.MAPPING_ISBRIDGE_CURRENCY &&
                    transfer.secondreserveid == address(0),
                        "Cannot convert non reserve");
        }
        else 
        {
            revert ("Invalid flag combination");
        }

        return true;

    }

    function reverse(uint64 input) public pure returns (int64) 
    {
        // swap bytes
        input = ((input & 0xFF00FF00FF00FF00) >> 8) |
            ((input & 0x00FF00FF00FF00FF) << 8);

        // swap 2-byte long pairs
        input = ((input & 0xFFFF0000FFFF0000) >> 16) |
            ((input & 0x0000FFFF0000FFFF) << 16);

        // swap 4-byte long pairs
        input = (input >> 32) | (input << 32);

        return int64(input);
    }

    function convertFromVerusNumber(uint256 a,uint8 decimals) public pure returns (uint256) {
        uint8 power = 10; //default value for 18
        uint256 c = a;

        if(decimals > 8 ) {
            power = decimals - 8;// number of decimals in verus
            c = a * (10 ** power);
        }else if(decimals < 8){
            power = 8 - decimals;// number of decimals in verus
            c = a / (10 ** power);
        }

        return c;
    }
}

contracts/VerusBridge/SubmitImports.sol.content:
// SPDX-License-Identifier: MIT
// Bridge between ethereum and verus

pragma solidity >=0.8.9;
pragma abicoder v2;

import "../Libraries/VerusObjects.sol";
import "../Libraries/VerusConstants.sol";
import "./Token.sol";
import "../Storage/StorageMaster.sol";
import "./CreateExports.sol";
import "./TokenManager.sol";


contract SubmitImports is VerusStorage {

    address immutable VETH;
    address immutable BRIDGE;
    address immutable VERUS;
    address immutable DAI;
    address immutable MKR;

    constructor(address vETH, address Bridge, address Verus, address Dai, address Mkr){

        VETH = vETH;
        BRIDGE = Bridge;
        VERUS = Verus;
        DAI = Dai;
        MKR = Mkr;
    }

    uint32 constant ELVCHOBJ_TXID_OFFSET = 32;
    uint32 constant ELVCHOBJ_NVINS_OFFSET = 45;
    uint32 constant FORKS_NOTARY_PROPOSER_POSITION = 96;
    uint32 constant TYPE_REFUND = 1;
    uint constant TYPE_BYTE_LOCATION_IN_UINT176 = 168;
    uint8 constant TYPE_REFUND_BYTES32_LOCATION = 244;
    enum Currency {VETH, DAI, VERUS, MKR}

    function initialize() external {

    }

    function buildReserveTransfer (uint64 value, uint176 sendTo, address sendingCurrency, uint64 fees, address feecurrencyid) private view returns (VerusObjects.CReserveTransfer memory) {

        VerusObjects.CReserveTransfer memory LPtransfer;

        LPtransfer.version = 1;
        LPtransfer.destination.destinationtype = uint8(sendTo >> TYPE_BYTE_LOCATION_IN_UINT176);
        LPtransfer.destcurrencyid = BRIDGE;
        LPtransfer.destsystemid = address(0);
        LPtransfer.secondreserveid = address(0);
        LPtransfer.flags = VerusConstants.VALID;
        LPtransfer.destination.destinationaddress = abi.encodePacked(uint160(sendTo));
        LPtransfer.currencyvalue.currency = sendingCurrency;
        LPtransfer.feecurrencyid = feecurrencyid;
        LPtransfer.fees = fees;
        LPtransfer.currencyvalue.amount = value;          

        return LPtransfer;
    }

    function sendBurnBackToVerus (uint64 sendAmount, address currency, uint64 fees) public view returns (VerusObjects.CReserveTransfer memory) {

        VerusObjects.CReserveTransfer memory LPtransfer;

        if (currency == VERUS) {
            LPtransfer =  buildReserveTransfer(uint64(remainingLaunchFeeReserves - VerusConstants.verusTransactionFee),
                                               uint176(VerusConstants.VDXFID_VETH_BURN_ADDRESS),
                                               VERUS,
                                               VerusConstants.verusTransactionFee,
                                               VERUS );
        } else if (currency == DAI) {
            LPtransfer =  buildReserveTransfer(sendAmount,
                                               uint176(VerusConstants.VDXFID_VETH_BURN_ADDRESS),
                                               DAI,
                                               fees,
                                               DAI );
        } 

        LPtransfer.flags += VerusConstants.BURN_CHANGE_PRICE ;

        return LPtransfer;
    }

    function getImportFeeForReserveTransfer(address currency) public view returns (uint64) {

        uint64 feeShare;
        uint feeCalculation;
        uint reserves = claimableFees[bytes32(uint256(uint160(VerusConstants.VDXF_ETH_DAI_VRSC_LAST_RESERVES)))];

        // Get the uint64 location in the uint256 word to calculate fees
        if (currency == DAI){
            feeCalculation = uint(Currency.DAI) << 6;
        } else if (currency == MKR){
            feeCalculation = uint(Currency.MKR) << 6;
        } else if (currency == VETH) {
            feeCalculation = uint(Currency.VETH) << 6;
        } else if (currency == VERUS) {
            return uint64(VerusConstants.VERUS_IMPORT_FEE);
        } else {
            // NOTE: Bridge.vETH currency is not supported.
            revert();
        }      

        feeCalculation = VerusConstants.VERUS_IMPORT_FEE_X2 * uint64(reserves >> feeCalculation);
        feeShare = uint64(feeCalculation / uint(uint64(reserves >> (uint(Currency.VERUS) << 6))));

        return feeShare;
    }

    function _createImports(bytes calldata data) external returns(uint64, uint176) {

        uint256 gasleftStart = gasleft();
        VerusObjects.CReserveTransferImport memory _import = abi.decode(data, (VerusObjects.CReserveTransferImport));
        bytes32 txidfound;
        bytes memory elVchObj = _import.partialtransactionproof.components[0].elVchObj;
        uint32 nVins;

        assembly
        {
            txidfound := mload(add(elVchObj, ELVCHOBJ_TXID_OFFSET)) 
            nVins := mload(add(elVchObj, ELVCHOBJ_NVINS_OFFSET)) 
        }

        if (processedTxids[txidfound]) 
        {
            revert();
        } 

        bool success;
        bytes memory returnBytes;

        // reverse 32bit endianess
        nVins = ((nVins & 0xFF00FF00) >> 8) |  ((nVins & 0x00FF00FF) << 8);
        nVins = (nVins >> 16) | (nVins << 16);

        bytes32 hashOfTransfers;

        // [0..139]address of reward recipricent and [140..203]int64 fees
        uint64 fees;

        // [0..31]startheight [32..63]endheight [64..95]nIndex, [96..128] numberoftransfers packed into a uint128  
        uint128 CCEHeightsAndnIndex;

        hashOfTransfers = keccak256(_import.serializedTransfers);

        address verusProofAddress = contracts[uint(VerusConstants.ContractType.VerusProof)];

        (success, returnBytes) = verusProofAddress.delegatecall(abi.encodeWithSignature("proveImports(bytes)", abi.encode(_import, hashOfTransfers)));
        require(success);
        uint176 exporter;
        (CCEHeightsAndnIndex, exporter) = abi.decode(returnBytes, (uint128, uint176));

        // remove auxdest flags off exporter type.
        exporter = exporter & 0x0fffffffffffffffffffffffffffffffffffffffffff;

        isLastCCEInOrder(uint32(CCEHeightsAndnIndex));

        // clear 4 bytes above first 64 bits, i.e. clear the nIndex 32 bit number, then convert to correct nIndex
        // Using the index for the proof (ouput of an export) - (header ( 2 * nvin )) == export output
        // NOTE: This depends on the serialization of the CTransaction header and the location of the vins being 45 bytes in.
        // NOTE: Also depends on it being a partial transaction proof, header = 1

        CCEHeightsAndnIndex  = (CCEHeightsAndnIndex & 0xffffffff00000000ffffffffffffffff) | (uint128(uint32(uint32(CCEHeightsAndnIndex >> 64) - (1 + (2 * nVins)))) << 64);  
        setLastImport(txidfound, hashOfTransfers, CCEHeightsAndnIndex);

        // get the gasleft before calling the tokenmanager

        //returns success, refund addresses bytes & refund address array which is abi.encoded-ed, these are any refunds that didnt pay out.
        (success, returnBytes) = contracts[uint(VerusConstants.ContractType.TokenManager)].delegatecall(abi.encodeWithSelector(TokenManager.processTransactions.selector, _import.serializedTransfers, uint256(uint8(CCEHeightsAndnIndex >> 96))));
        require(success);

        uint176[] memory refundAddresses;

        // returns refundaddresses bytes, fees and refundaddresses
        (returnBytes, fees, refundAddresses) = abi.decode(returnBytes, (bytes, uint64, uint176[]));

        // get the cceblockwidth of the cce from endheight - startheight and copy back into CCEHeightsAndnIndex
        CCEHeightsAndnIndex = (uint32(CCEHeightsAndnIndex >> 32) - uint32(CCEHeightsAndnIndex));

        // calculate the fee to pay any refunds, and then pay to the refund addresses.
        calulateGasFees(gasleftStart, fees, refundAddresses, CCEHeightsAndnIndex, exporter);

        if (returnBytes.length > 0) {
            refund(returnBytes);
        }
        return (0,0);
    }

    function calulateGasFees(uint256 gasStart, uint64 fees, uint176[] memory refundAddresses, uint256 blockWidth, uint176 exporter) private {

        uint256 priceOfImports; // ETH price of the imports calculated from gas used.
        uint64 notaryFees;   // fees to pay to notaries
        uint64 blockDivisor; // ratio adjustment when traffic is high
        uint64 minTxesForRefund; // minimum number of transactions for a refund
        uint64 feeRefunds;
        uint64 processorsFees; // fees shared out between notaries / exporters / proposers.

        // Using the gas used gives us an indication of how much the transaction will cost.
        // i.e. the gas used to do 2 * notaryimports + fixedcost for submitimport + (gas to process the tx payements)
        priceOfImports = uint256((gasStart - gasleft()) + VerusConstants.GAS_BASE_COST_FOR_NOTARYS + 
            (refundAddresses.length * VerusConstants.GAS_BASE_COST_FOR_REFUND_PAYOUTS)) 
            * tx.gasprice;

        // Use a Buffer of 40% for notary fees. (In Verus sats)
        notaryFees = uint64(((priceOfImports * 14) / 10) / VerusConstants.SATS_TO_WEI_STD); 

        if (fees > (notaryFees + (notaryFees >> 4))){

            blockDivisor = 20;
            minTxesForRefund = VerusConstants.MINIMUM_TRANSACTIONS_FOR_REFUNDS;

            if (blockWidth > 1)
            {
                blockDivisor = 10;
                minTxesForRefund = VerusConstants.MINIMUM_TRANSACTIONS_FOR_REFUNDS_HALF;
            }

            if (refundAddresses.length > minTxesForRefund)
            {
                processorsFees = fees - notaryFees;
                fees = notaryFees;

                feeRefunds = uint64((processorsFees / refundAddresses.length) * (refundAddresses.length - minTxesForRefund));
                feeRefunds = feeRefunds - (feeRefunds / blockDivisor);
                processorsFees = processorsFees - feeRefunds;

                // Divide by number of transactions to get refund share per number of transfers.
                feeRefunds = feeRefunds / uint64(refundAddresses.length);

                for(uint i = 0; i < refundAddresses.length; i++) {
                    bytes32 feeRefundAddress;
                    feeRefundAddress = bytes32(uint256(refundAddresses[i]));

                    if (feeRefundAddress != bytes32(0)) {
                        feeRefundAddress |= bytes32(uint256(TYPE_REFUND) << TYPE_REFUND_BYTES32_LOCATION);
                        refunds[feeRefundAddress][VETH] += feeRefunds;
                    } else {
                        processorsFees += feeRefunds;                    
                    }
                }
            } else {
                processorsFees = fees - notaryFees;
                fees = notaryFees;
            }
        } 

        setClaimableFees(fees, exporter, processorsFees);
    }

    function refund(bytes memory refundAmount) private  {

        if (refundAmount.length < 50) return; //early return if no refunds.

        // Note each refund is 50 bytes = 22bytes(uint176) + uint64 + uint160 (currency)
        for(uint i = 0; i < refundAmount.length; i = i + 50) {

            uint176 verusAddress;
            uint64 amount;
            address currency;
            assembly 
            {
                verusAddress := mload(add(add(refundAmount, 22), i))
                amount := mload(add(add(refundAmount, 30), i))
                currency := mload(add(add(refundAmount, 50), i))
            }

            bytes32 refundAddress;

            // The leftmost byte is the TYPE_REFUND;
            refundAddress = bytes32(uint256(verusAddress) | uint256(TYPE_REFUND) << TYPE_REFUND_BYTES32_LOCATION);

            refunds[refundAddress][currency] += amount;

        }
     }

    function setLastImport(bytes32 processedTXID, bytes32 hashofTXs, uint128 CCEheightsandTXNum ) private {

        processedTxids[processedTXID] = true;
       // lastTxIdImport = processedTXID;
        lastImportInfo[VerusConstants.SUBMIT_IMPORTS_LAST_TXID] = VerusObjects.lastImportInfo(hashofTXs, processedTXID, uint32(CCEheightsandTXNum >> 64), uint32(CCEheightsandTXNum >> 32));
    } 

    function isLastCCEInOrder(uint32 height) private view {

        if ((lastImportInfo[VerusConstants.SUBMIT_IMPORTS_LAST_TXID].height + 1) == height)
        {
            return;
        } 
        else if (lastImportInfo[VerusConstants.SUBMIT_IMPORTS_LAST_TXID].hashOfTransfers == bytes32(0))
        {
            return;
        } 
        else{
            revert();
        }
    }

    function getReadyExportsByRange(uint _startBlock,uint _endBlock) external view returns(VerusObjects.CReserveTransferSetCalled[] memory returnedExports){

        uint outputSize;
        uint heights = _startBlock;
        bool loop = cceLastEndHeight > 0;

        if(!loop) return returnedExports;

        while(loop){

            heights = _readyExports[heights].endHeight + 1;
            if (heights > _endBlock || heights == 1) {
                break;
            }
            outputSize++;
        }

        returnedExports = new VerusObjects.CReserveTransferSetCalled[](outputSize);
        VerusObjects.CReserveTransferSet memory tempSet;
        heights = _startBlock;

        for (uint i = 0; i < outputSize; i++)
        {
            tempSet = _readyExports[heights];
            returnedExports[i] = VerusObjects.CReserveTransferSetCalled(tempSet.exportHash, tempSet.prevExportHash, uint64(heights), tempSet.endHeight, tempSet.transfers);
            heights = tempSet.endHeight + 1;
        }
        return returnedExports;      
    }

    function setClaimableFees(uint64 notaryFees, uint176 exporter, uint64 processorsFees) private 
    {
        uint64 feeShare;
        feeShare = processorsFees / 3;

        claimableFees[VerusConstants.VDXF_SYSTEM_NOTARIZATION_NOTARYFEEPOOL] += (notaryFees + feeShare);

        if (processorsFees > 0) {

            bytes memory proposerBytes = bestForks[0];
            uint176 proposer;

            assembly {
                    proposer := mload(add(proposerBytes, FORKS_NOTARY_PROPOSER_POSITION))
            } 

            setClaimedFees(bytes32(uint256(proposer)), feeShare); // 1/3 to proposer
            setClaimedFees(bytes32(uint256(exporter)), feeShare + (feeShare % 3)); // any remainder from main division goes to exporter
        }
    }

    function setClaimedFees(bytes32 _address, uint256 fees) private  {

        claimableFees[_address] += fees;
    }

    function claimfees() public {

        uint256 claimAmount;

        if ((claimableFees[VerusConstants.VDXF_SYSTEM_NOTARIZATION_NOTARYFEEPOOL] * VerusConstants.SATS_TO_WEI_STD) > VerusConstants.CLAIM_NOTARY_FEE_THRESHOLD)
        {
            uint256 txReimburse;

            // truncate reimburse amount
            txReimburse = ((tx.gasprice * VerusConstants.NOTARY_CLAIM_TX_GAS_COST) / VerusConstants.SATS_TO_WEI_STD) * VerusConstants.SATS_TO_WEI_STD;

            if (claimableFees[bytes32(0)] > 0) {
                // When there is no proposer fees are sent to bytes(0)
                claimableFees[VerusConstants.VDXF_SYSTEM_NOTARIZATION_NOTARYFEEPOOL] += claimableFees[bytes32(0)];
                claimableFees[bytes32(0)] = 0;
            }

            claimAmount = claimableFees[VerusConstants.VDXF_SYSTEM_NOTARIZATION_NOTARYFEEPOOL] - (txReimburse / VerusConstants.SATS_TO_WEI_STD);

            claimableFees[VerusConstants.VDXF_SYSTEM_NOTARIZATION_NOTARYFEEPOOL] = 0;

            uint256 claimShare;

            claimShare = claimAmount / notaries.length;

            for (uint i = 0; i < notaries.length; i++)
            {
                if (notaryAddressMapping[notaries[i]].state == VerusConstants.NOTARY_VALID)
                {
                    claimAmount -= claimShare;
                    payable(notaryAddressMapping[notaries[i]].main).transfer(claimShare * VerusConstants.SATS_TO_WEI_STD);
                }
            }
            claimableFees[VerusConstants.VDXF_SYSTEM_NOTARIZATION_NOTARYFEEPOOL] = claimAmount;
            payable(msg.sender).transfer(txReimburse);
        }
    }

    function claimRefund(uint176 verusAddress, address currency) external payable returns (uint)
    {
        uint256 refundAmount;
        bytes32 refundAddressFormatted;
        VerusObjects.CReserveTransfer memory LPtransfer;
        bool success;
        refundAddressFormatted = bytes32(uint256(verusAddress) | uint256(TYPE_REFUND) << TYPE_REFUND_BYTES32_LOCATION);

        refundAmount = refunds[refundAddressFormatted][currency];
        require (bridgeConverterActive && refundAmount > 0 && verusAddress != uint176(0));

        delete refunds[refundAddressFormatted][currency];
        uint64 fees;
        address feeCurrency;

        if (currency != VETH && currency != DAI && currency != VERUS && currency != MKR) {
            fees = getImportFeeForReserveTransfer(VETH);
            if (msg.value < (fees * VerusConstants.SATS_TO_WEI_STD)) {
                revert();
            }
            //The user may have put too much in, so update fees for correct accounting.
            fees = uint64(msg.value / VerusConstants.SATS_TO_WEI_STD);
            feeCurrency = VETH;
        } else {
            fees = getImportFeeForReserveTransfer(currency);
            require (refundAmount > fees);
            feeCurrency = currency;
        }

        LPtransfer = buildReserveTransfer(uint64(refundAmount), verusAddress, currency, fees, feeCurrency);

        (success, ) = contracts[uint(VerusConstants.ContractType.CreateExport)]
                            .delegatecall(abi.encodeWithSelector(CreateExports.externalCreateExportCallPayable.selector, abi.encode(LPtransfer, false)));
        require(success);

        return 0;

    }

    // Caclulates the amount of DAI, MKR or VERUS to reimburse the user for the transaction fee.
    function getTxFeeReimbursement (address currency) private view returns (uint64) {

        uint256 txReimburse;
        // keep the Reimburse value in wei until end for accuracy
        txReimburse = (tx.gasprice * VerusConstants.REFUND_FEE_REIMBURSE_GAS_AMOUNT);

        uint reserves = claimableFees[bytes32(uint256(uint160(VerusConstants.VDXF_ETH_DAI_VRSC_LAST_RESERVES)))];
        uint feeCalculation;
        // multiply the ETH amount by the reserve of ETH
        // Get the uint64 location in the uin256 word to calculate fees
        if (currency == DAI){
            feeCalculation = uint(Currency.DAI) << 6;
        } else if (currency == MKR){
            feeCalculation = uint(Currency.MKR) << 6;
        } else if (currency == VERUS) {
            feeCalculation = uint(Currency.VERUS) << 6;
        } else {
            // NOTE: Bridge.vETH currency is not supported.
            revert();
        }      

        // multiply the ETH amount by the reserves of the chosen currency
        txReimburse = txReimburse * uint64(reserves >> feeCalculation);
        txReimburse = (txReimburse / uint(uint64(reserves >> (uint(Currency.VETH) << 6)))) / VerusConstants.SATS_TO_WEI_STD;

        return uint64(txReimburse);

    }

    function sendfees(bytes32 publicKeyX, bytes32 publicKeyY) public 
    {
        require(bridgeConverterActive);
        uint8 leadingByte;
        uint256 claimant; 
        uint64 feeShare;

        leadingByte = (uint256(publicKeyY) & 1) == 1 ? 0x03 : 0x02;
        claimant = uint160(ripemd160(abi.encodePacked(sha256(abi.encodePacked(leadingByte, publicKeyX)))));
        claimant |= (uint256(0x0214) << VerusConstants.UINT160_BITS_SIZE);  // is Claimient type R address and 20 bytes.

        if ((claimableFees[bytes32(claimant)] > VerusConstants.verusvETHTransactionFee) 
                && msg.sender == address(uint160(uint256(keccak256(abi.encodePacked(publicKeyX, publicKeyY))))))
        {
            feeShare = uint64(claimableFees[bytes32(claimant)]);
            claimableFees[bytes32(claimant)] = 0;
            payable(msg.sender).transfer(feeShare * VerusConstants.SATS_TO_WEI_STD);
            return;
        }

        if ((claimableFees[publicKeyX] > (VerusConstants.verusvETHTransactionFee << 1))) {
            require(publicKeyX[10]  == 0x04);
            require(claimableFees[publicKeyX] > VerusConstants.verusvETHTransactionFee);
            feeShare = uint64(claimableFees[publicKeyX]) - VerusConstants.verusvETHTransactionFee;
            claimableFees[publicKeyX] = 0;
            VerusObjects.CReserveTransfer memory LPtransfer;
            LPtransfer = buildReserveTransfer(feeShare, uint176(uint256(publicKeyX)), VETH, VerusConstants.verusvETHTransactionFee, VETH);
            (bool success, ) = contracts[uint(VerusConstants.ContractType.CreateExport)]
                                .delegatecall(abi.encodeWithSelector(CreateExports.externalCreateExportCallPayable.selector, abi.encode(LPtransfer, false)));
            require(success);
        }

    }

    function convertFromVerusNumber(uint256 a,uint8 decimals) private pure returns (uint256) {
        uint8 power = 10; //default value for 18
        uint256 c = a;

        if(decimals > 8 ) {
            power = decimals - 8;// number of decimals in verus
            c = a * (10 ** power);
        }else if(decimals < 8){
            power = 8 - decimals;// number of decimals in verus
            c = a / (10 ** power);
        }

        return c;
    }

}

